preConditionHook:
// THE SECOND ENTRY -- Brooks's most-repeated reliability filter, and the one
// condition he says is sufficient on its own. An earlier same-side signal
// triggered within the last withinBars bars, that first entry failed, and a
// new same-side signal is triggering now.
//
// THE DEFINITION OF 'THE SAME SIGNAL' IS THE CONCRETE PROXY, chosen by the
// merge pass over a generic setup-identity registry: the signal is the
// generic price trigger -- a close above the prior bar's high -- and the
// failure is price trading back beyond that signal bar's opposite extreme.
// The registry version would need a per-placement fire/fail log the engine
// does not have. THE LOSS IS REAL AND DELIBERATE: this counts a second
// GENERIC trigger, not a second instance of whichever pattern the pane is
// actually trading.
//
// Bar kk is the earlier trigger bar and bar kk + 1 its signal bar. The
// failure window is the kk - 1 bars ENDING AT THE CURRENT BAR, exactly as the
// merged pseudocode spells it, which is why the outer scan starts at 2 -- at
// kk = 2 that window is the current bar alone. The inner loop is a running
// extreme rather than a Lowest() call because the length is a loop variable;
// at kk = 2 it does not execute, in EasyLanguage and here alike.
//
// Both flags are cleared at the top and both sides are computed here rather
// than in the conditions: EasyLanguage does not short-circuit, so a scan in a
// condition would run on every bar in EL and only on some bars in C++.
//
// Not LastTradeCooldown: that gates on a REALIZED trade's outcome through
// PositionProfit(1) and BarsSinceExit. This gates on a repeated raw pattern
// whether or not a trade was ever taken, and can fire before any trade
// exists.
secondUp = false;
secondDn = false;
for (kk = 2; kk <= (int)withinBars; ++kk) {
    runLow = low[0];
    runHigh = high[0];
    for (jj = 1; jj <= kk - 2; ++jj) {
        if (el_lt(low[jj], runLow)) runLow = low[jj];
        if (el_gt(high[jj], runHigh)) runHigh = high[jj];
    }
    if (el_gt(close[kk], high[kk + 1]) && el_lt(runLow, low[kk + 1])) secondUp = true;
    if (el_lt(close[kk], low[kk + 1]) && el_gt(runHigh, high[kk + 1])) secondDn = true;
}
